insert into public.products (slug,category,brand,collection,name,material,style,color,price,description,features,image_path,sort_order,is_available)
select slug,'entrance','Abwehr','Classic Prime',name,'Сталь, МДФ-накладки та заводські покриття','Сучасний','Заводські декори','Ціна за запитом',name || ' — вхідні двері для квартири серії Classic Prime. Три контури ущільнення та утеплена конструкція допомагають зберігати комфорт у приміщенні; точну комплектацію, декори й ціну уточнюйте у менеджера.',jsonb_build_array('Фабрика Abwehr','Колекція Classic Prime','3 контури ущільнення'),images[1],99999,false from abwehr_classic_next
on conflict(slug) do update set name=excluded.name,description=excluded.description,features=excluded.features,image_path=excluded.image_path;
insert into public.product_specs(product_slug,label,value,sort_order,is_active)
select slug,label,value,sort_order,true from abwehr_classic_next cross join lateral(values('Тип конструкції','Вхідні двері для квартири',10),('Колекція','Classic Prime',20),('Призначення','Для квартири',30),('Контури ущільнення','3 контури',40))spec(label,value,sort_order)
on conflict(product_slug,label) do update set value=excluded.value,sort_order=excluded.sort_order,is_active=true;
insert into public.product_sources(product_slug,source_name,source_url,source_product_name,verification_status,verified_at,notes)
select slug,'ABWEHR',source_url,name || ' · Classic Prime · код ' || code,'verified',now(),'Офіційна картка виробника: окрема актуальна модель Classic Prime та фотогалерея.' from abwehr_classic_next
where not exists(select 1 from public.product_sources s where s.product_slug=abwehr_classic_next.slug and s.source_url=abwehr_classic_next.source_url);
insert into public.product_media(product_slug,kind,label,image_path,sort_order)
select slug,'main','Головне фото',images[1],0 from abwehr_classic_next where not exists(select 1 from public.product_media m where m.product_slug=abwehr_classic_next.slug and m.kind='main' and m.image_path=abwehr_classic_next.images[1]);
insert into public.product_media(product_slug,kind,label,image_path,sort_order)
select model.slug,'gallery','Офіційне фото ' || picture.ordinality,picture.image_path,picture.ordinality from abwehr_classic_next model cross join lateral unnest(model.images) with ordinality as picture(image_path,ordinality)
where not exists(select 1 from public.product_media m where m.product_slug=model.slug and m.kind='gallery' and m.image_path=picture.image_path);
commit;
select count(*) as моделей,count(*) filter(where is_available) as опубліковано,(select count(*) from public.product_media m where m.product_slug in('abwehr-classic-elaria-official','abwehr-classic-laguna-official','abwehr-classic-rain-official','abwehr-classic-rail-official','abwehr-classic-studio-official','abwehr-classic-liana-official') and m.kind='gallery') as фото_в_галереях,count(*) filter(where image_path is not null) as моделей_з_фото from public.products where slug in('abwehr-classic-elaria-official','abwehr-classic-laguna-official','abwehr-classic-rain-official','abwehr-classic-rail-official','abwehr-classic-studio-official','abwehr-classic-liana-official');
